```python
"""
MythTV API Client Library

A Python library for interacting with MythTV backend services.
Supports both the legacy HTTP API and the newer Services API.
"""

import requests
import xml.etree.ElementTree as ET
from datetime import datetime
from typing import Dict, List, Optional, Any, Union
from urllib.parse import urljoin, urlencode
import json
import logging

# Configure logging
logger = logging.getLogger(__name__)


class MythTVError(Exception):
    """Base exception for MythTV API errors"""
    pass


class MythTVConnectionError(MythTVError):
    """Raised when connection to MythTV backend fails"""
    pass


class MythTVAPIError(MythTVError):
    """Raised when API returns an error"""
    pass


class MythTVClient:
    """
    Main client class for interacting with MythTV backend.

    Example:
        client = MythTVClient('192.168.1.100', port=6544)
        channels = client.channel.get_channel_list()
    """

    def __init__(self, host: str, port: int = 6544, username: Optional[str] = None, 
                 password: Optional[str] = None, timeout: int = 30):
        """
        Initialize MythTV client.

        Args:
            host: MythTV backend hostname or IP
            port: Backend services port (default: 6544)
            username: Optional username for authentication
            password: Optional password for authentication
            timeout: Request timeout in seconds
        """
        self.host = host
        self.port = port
        self.base_url = f"http://{host}:{port}"
        self.timeout = timeout
        self.session = requests.Session()

        if username and password:
            self.session.auth = (username, password)

        # Initialize service modules
        self.channel = ChannelService(self)
        self.dvr = DVRService(self)
        self.guide = GuideService(self)
        self.content = ContentService(self)
        self.myth = MythService(self)
        self.capture = CaptureService(self)
        self.video = VideoService(self)

        # Test connection
        self._test_connection()

    def _test_connection(self):
        """Test connection to MythTV backend"""
        try:
            response = self._request('GET', '/Myth/GetHostName')
            if response.status_code != 200:
                raise MythTVConnectionError(f"Failed to connect to MythTV backend at {self.base_url}")
        except requests.exceptions.RequestException as e:
            raise MythTVConnectionError(f"Connection error: {str(e)}")

    def _request(self, method: str, endpoint: str, params: Optional[Dict] = None, 
                 data: Optional[Dict] = None, headers: Optional[Dict] = None) -> requests.Response:
        """
        Make HTTP request to MythTV backend.

        Args:
            method: HTTP method (GET, POST, etc.)
            endpoint: API endpoint path
            params: Query parameters
            data: Request body data
            headers: Additional headers

        Returns:
            Response object
        """
        url = urljoin(self.base_url, endpoint)

        try:
            response = self.session.request(
                method=method,
                url=url,
                params=params,
                data=data,
                headers=headers,
                timeout=self.timeout
            )
            response.raise_for_status()
            return response
        except requests.exceptions.RequestException as e:
            logger.error(f"Request failed: {method} {url} - {str(e)}")
            raise MythTVAPIError(f"API request failed: {str(e)}")

    def _get(self, endpoint: str, params: Optional[Dict] = None) -> Dict:
        """Make GET request and return JSON response"""
        response = self._request('GET', endpoint, params=params)
        return self._parse_response(response)

    def _post(self, endpoint: str, data: Optional[Dict] = None, params: Optional[Dict] = None) -> Dict:
        """Make POST request and return JSON response"""
        response = self._request('POST', endpoint, data=data, params=params)
        return self._parse_response(response)

    def _parse_response(self, response: requests.Response) -> Dict:
        """Parse response based on content type"""
        content_type = response.headers.get('Content-Type', '')

        if 'application/json' in content_type:
            return response.json()
        elif 'text/xml' in content_type or 'application/xml' in content_type:
            return self._xml_to_dict(response.text)
        else:
            return {'raw': response.text}

    def _xml_to_dict(self, xml_string: str) -> Dict:
        """Convert XML response to dictionary"""
        root = ET.fromstring(xml_string)
        return self._element_to_dict(root)

    def _element_to_dict(self, element: ET.Element) -> Union[Dict, str]:
        """Recursively convert XML element to dictionary"""
        result = {}

        # Add attributes
        if element.attrib:
            result['@attributes'] = element.attrib

        # Add text content
        if element.text and element.text.strip():
            if len(element) == 0:  # No children
                return element.text.strip()
            else:
                result['#text'] = element.text.strip()

        # Add children
        for child in element:
            child_data = self._element_to_dict(child)
            if child.tag in result:
                # Convert to list if multiple children with same tag
                if not isinstance(result[child.tag], list):
                    result[child.tag] = [result[child.tag]]
                result[child.tag].append(child_data)
            else:
                result[child.tag] = child_data

        return result if result else element.text


class BaseService:
    """Base class for MythTV service modules"""

    def __init__(self, client: MythTVClient):
        self.client = client


class ChannelService(BaseService):
    """Channel service for managing channels"""

    def get_channel_list(self, source_id: Optional[int] = None, start_index: int = 0, 
                        count: Optional[int] = None) -> List[Dict]:
        """
        Get list of channels.

        Args:
            source_id: Optional source ID to filter channels
            start_index: Starting index for pagination
            count: Number of channels to return

        Returns:
            List of channel dictionaries
        """
        params = {
            'StartIndex': start_index
        }
        if source_id:
            params['SourceID'] = source_id
        if count:
            params['Count'] = count

        response = self.client._get('/Channel/GetChannelInfoList', params=params)
        return response.get('ChannelInfoList', {}).get('ChannelInfos', [])

    def get_channel_info(self, chan_id: int) -> Dict:
        """Get information about a specific channel"""
        params = {'ChanID': chan_id}
        response = self.client._get('/Channel/GetChannelInfo', params=params)
        return response.get('ChannelInfo', {})

    def get_video_sources(self) -> List[Dict]:
        """Get list of video sources"""
        response = self.client._get('/Channel/GetVideoSourceList')
        return response.get('VideoSourceList', {}).get('VideoSources', [])

    def update_channel(self, chan_id: int, **kwargs) -> bool:
        """
        Update channel information.

        Args:
            chan_id: Channel ID
            **kwargs: Channel attributes to update (CallSign, ChannelName, etc.)

        Returns:
            True if successful
        """
        params = {'ChanID': chan_id}
        params.update(kwargs)
        response = self.client._post('/Channel/UpdateDBChannel', params=params)
        return response.get('bool', False)


class DVRService(BaseService):
    """DVR service for managing recordings"""

    def get_recorded_list(self, start_index: int = 0, count: Optional[int] = None,
                         title_filter: Optional[str] = None) -> List[Dict]:
        """
        Get list of recorded programs.

        Args:
            start_index: Starting index for pagination
            count: Number of recordings to return
            title_filter: Filter by title

        Returns:
            List of recorded program dictionaries
        """
        params = {
            'StartIndex': start_index
        }
        if count:
            params['Count'] = count
        if title_filter:
            params['TitleRegEx'] = title_filter

        response = self.client._get('/Dvr/GetRecordedList', params=params)
        return response.get('ProgramList', {}).get('Programs', [])

    def get_recorded(self, recorded_id: Optional[int] = None, chan_id: Optional[int] = None,
                    start_time: Optional[datetime] = None) -> Dict:
        """Get specific recorded program"""
        params = {}
        if recorded_id:
            params['RecordedId'] = recorded_id
        elif chan_id and start_time:
            params['ChanId'] = chan_id
            params['StartTime'] = start_time.isoformat()
        else:
            raise ValueError("Must provide either RecordedId or both ChanId and StartTime")

        response = self.client._get('/Dvr/GetRecorded', params=params)
        return response.get('Program', {})

    def get_upcoming_list(self, start_index: int = 0, count: Optional[int] = None,
                         show_all: bool = False) -> List[Dict]:
        """Get list of upcoming recordings"""
        params = {
            'StartIndex': start_index,
            'ShowAll': show_all
        }
        if count:
            params['Count'] = count

        response = self.client._get('/Dvr/GetUpcomingList', params=params)
        return response.get('ProgramList', {}).get('Programs', [])

    def get_recording_rules(self) -> List[Dict]:
        """Get all recording rules"""
        response = self.client._get('/Dvr/GetRecordScheduleList')
        return response.get('RecRuleList', {}).get('RecRules', [])

    def add_recording_rule(self, chan_id: int, start_time: datetime, 
                          rule_type: str = 'Single', **kwargs) -> int:
        """
        Add a new recording rule.

        Args:
            chan_id: Channel ID
            start_time: Start time of program
            rule_type: Type of rule (Single, Daily, Weekly, etc.)
            **kwargs: Additional rule parameters

        Returns:
            Recording rule ID
        """
        params = {
            'ChanId': chan_id,
            'StartTime': start_time.isoformat(),
            'Type': rule_type
        }
        params.update(kwargs)

        response = self.client._post('/Dvr/AddRecordSchedule', params=params)
        return response.get('uint', 0)

    def delete_recording(self, recorded_id: Optional[int] = None, chan_id: Optional[int] = None,
                        start_time: Optional[datetime] = None, force_delete: bool = False) -> bool:
        """Delete a recording"""
        params = {
            'ForceDelete': force_delete
        }

        if recorded_id:
            params['RecordedId'] = recorded_id
        elif chan_id and start_time:
            params['ChanId'] = chan_id
            params['StartTime'] = start_time.isoformat()
        else:
            raise ValueError("Must provide either RecordedId or both ChanId and StartTime")

        response = self.client._post('/Dvr/DeleteRecording', params=params)
        return response.get('bool', False)


class GuideService(BaseService):
    """Guide service for program guide data"""

    def get_program_guide(self, start_time: datetime, end_time: datetime,
                         chan_id: Optional[int] = None, num_channels: Optional[int] = None,
                         details: bool = True) -> Dict:
        """
        Get program guide data.

        Args:
            start_time: Start time for guide data
            end_time: End time for guide data
            chan_id: Optional channel ID to start from
            num_channels: Number of channels to include
            details: Include detailed program information

        Returns:
            Program guide dictionary
        """
        params = {
            'StartTime': start_time.isoformat(),
            'EndTime': end_time.isoformat(),
            'Details': details
        }
        if chan_id:
            params['StartChanId'] = chan_id
        if num_channels:
            params['NumChannels'] = num_channels

        response = self.client._get('/Guide/GetProgramGuide', params=params)
        return response.get('ProgramGuide', {})

    def get_program_list(self, chan_id: int, start_time: datetime, 
                        end_time: datetime) -> List[Dict]:
        """Get program list for a specific channel"""
        params = {
            'ChanId': chan_id,
            'StartTime': start_time.isoformat(),
            'EndTime': end_time.isoformat()
        }

        response = self.client._get('/Guide/GetProgramList', params=params)
        return response.get('ProgramList', {}).get('Programs', [])


class ContentService(BaseService):
    """Content service for file operations"""

    def get_file_list(self, storage_group: str = 'Default') -> List[Dict]:
        """Get list of files in a storage group"""
        params = {'StorageGroup': storage_group}
        response = self.client._get('/Content/GetFileList', params=params)
        return response.get('StringList', {}).get('String', [])

    def download_file(self, filename: str, storage_group: str = 'Default') -> bytes:
        """Download a file from storage group"""
        params = {
            'StorageGroup': storage_group,
            'FileName': filename
        }
        response = self.client._request('GET', '/Content/DownloadFile', params=params)
        return response.content

    def get_preview_image(self, chan_id: int, start_time: datetime, 
                         width: Optional[int] = None, height: Optional[int] = None) -> bytes:
        """Get preview image for a recording"""
        params = {
            'ChanId': chan_id,
            'StartTime': start_time.isoformat()
        }
        if width:
            params['Width'] = width
        if height:
            params['Height'] = height

        response = self.client._request('GET', '/Content/GetPreviewImage', params=params)
        return response.content


class MythService(BaseService):
    """Myth service for system information"""

    def get_hostname(self) -> str:
        """Get backend hostname"""
        response = self.client._get('/Myth/GetHostName')
        return response.get('String', '')

    def get_backend_info(self) -> Dict:
        """Get backend information"""
        return self.client._get('/Myth/GetBackendInfo')

    def get_setting(self, key: str, hostname: Optional[str] = None) -> str:
        """Get a setting value"""
        params = {'Key': key}
        if hostname:
            params['HostName'] = hostname

        response = self.client._get('/Myth/GetSetting', params=params)
        return response.get('String', '')

    def put_setting(self, key: str, value: str, hostname: Optional[str] = None) -> bool:
        """Set a setting value"""
        params = {
            'Key': key,
            'Value': value
        }
        if hostname:
            params['HostName'] = hostname

        response = self.client._post('/Myth/PutSetting', params=params)
        return response.get('bool', False)

    def get_connection_info(self) -> Dict:
        """Get connection information for all backends"""
        return self.client._get('/Myth/GetConnectionInfo')

    def get_storage_group_dirs(self, group_name: Optional[str] = None) -> List[Dict]:
        """Get storage group directories"""
        params = {}
        if group_name:
            params['GroupName'] = group_name

        response = self.client._get('/Myth/GetStorageGroupDirs', params=params)
        return response.get('StorageGroupDirList', {}).get('StorageGroupDirs', [])


class CaptureService(BaseService):
    """Capture service for managing capture cards"""

    def get_capture_card_list(self) -> List[Dict]:
        """Get list of capture cards"""
        response = self.client._get('/Capture/GetCaptureCardList')
        return response.get('CaptureCardList', {}).get('CaptureCards', [])

    def get_capture_card(self, card_id: int) -> Dict:
        """Get specific capture card information"""
        params = {'CardId': card_id}
        response = self.client._get('/Capture/GetCaptureCard', params=params)
        return response.get('CaptureCard', {})

    def get_card_type_list(self) -> List[str]:
        """Get list of available card types"""
        response = self.client._get('/Capture/GetCardTypeList')
        return response.get('StringList', {}).get('String', [])


class VideoService(BaseService):
    """Video service for video library"""

    def get_video_list(self, folder: Optional[str] = None, start_index: int = 0,
                      count: Optional[int] = None) -> List[Dict]:
        """Get list of videos"""
        params = {
            'StartIndex': start_index
        }
        if folder:
            params['Folder'] = folder
        if count:
            params['Count'] = count

        response = self.client._get('/Video/GetVideoList', params=params)
        return response.get('VideoMetadataInfoList', {}).get('VideoMetadataInfos', [])

    def get_video(self, video_id: int) -> Dict:
        """Get specific video information"""
        params = {'Id': video_id}
        response = self.client._get('/Video/GetVideo', params=params)
        return response.get('VideoMetadataInfo', {})

    def lookup_video(self, title: str, subtitle: Optional[str] = None,
                    inetref: Optional[str] = None) -> Dict:
        """Lookup video metadata"""
        params = {'Title': title}
        if subtitle:
            params['Subtitle'] = subtitle
        if inetref:
            params['Inetref'] = inetref

        response = self.client._get('/Video/LookupVideo', params=params)
        return response.get('VideoLookupList', {})


