    def delete_recording(self, recorded_id: Optional[int] = None, chan_id: Optional[int] = None,
                        start_time: Optional[datetime] = None, force_delete: bool = False) -> bool:
        """Delete a recording"""
        params = {
            'ForceDelete': force_delete
        }

        if recorded_id:
            params['RecordedId'] = recorded_id
        elif chan_id and start_time:
            params['ChanId'] = chan_id
            params['StartTime'] = start_time.isoformat()
        else:
            raise ValueError("Must provide either RecordedId or both ChanId and StartTime")

        response = self.client._post('/Dvr/DeleteRecording', params=params)
        return response.get('bool', False)


